 renderChampionshipResults(){const s=this.state,c=s.championship||{},own=c.ownPositions||[],top=c.leaderboard||[],round=c.roundLeaderboard||[];$('root').innerHTML=`<div class="championshipResults"><section class="championshipResultsHero"><span>🏆 CAMPEONATO LA GORDA</span><h1>Ronda ${Number(c.currentRound)||1} finalizada</h1><p>Los puntos ya quedaron guardados. En la próxima ronda todos reciben matrices nuevas al azar.</p></section><div class="championshipResultsGrid"><section class="panel"><h2>RESULTADO DE LA RONDA</h2>${round.slice(0,10).map(x=>`<div class="champRow ${x.playerId===s.player?.id?'own':''}"><b>${x.rank}º</b><span>${esc(x.playerName)} · ${esc(x.label)}</span><strong>+${Number(x.roundPoints)||0}</strong></div>`).join('')}</section><section class="panel"><h2>CLASIFICACIÓN GENERAL</h2>${top.slice(0,10).map(x=>`<div class="champRow ${x.playerId===s.player?.id?'own':''}"><b>${x.rank}º</b><span>${esc(x.playerName)} · ${esc(x.label)}</span><strong>${Number(x.points)||0}</strong></div>`).join('')}</section></div><section class="panel championshipOwn"><h2>TUS CARTONES</h2>${own.map(x=>`<div class="champRow"><b>${esc(x.label)}</b><span>${Number(x.rank)||'—'}º general · +${Number(x.roundPoints)||0} esta ronda</span><strong>${Number(x.points)||0} pts</strong></div>`).join('')}</section><div class="actions championshipNextActions">${c.canNextRound?`<button id="championshipNextBtn" class="btn primary">▶ INICIAR RONDA ${Number(c.currentRound)+1}</button>`:`<div class="notice"><b>ESPERANDO AL CREADOR</b><br>La siguiente ronda comenzará cuando quien creó la sala la inicie.</div>`}<a class="btn secondary" href="/comunidad?quedar=1">VER COMUNIDAD</a></div></div>`;if($('championshipNextBtn'))$('championshipNextBtn').onclick=()=>this.nextChampionshipRound();this.syncChatDock();this.renderChat()}
