 renderPlayerWinnerTicker(entries){const host=$('playerWinnerTicker'),main=$('winnerTickerMain'),sub=$('winnerTickerSub'),dots=$('winnerTickerDots');if(!host||!main||!sub||!dots)return;if(!entries.length){host.classList.add('empty');host.classList.remove('hasWinners');main.textContent='Esperando el primer ganador';sub.textContent='Buena suerte';dots.innerHTML='';return}host.classList.remove('empty');host.classList.add('hasWinners');this.winnerTickerIndex=((this.winnerTickerIndex%entries.length)+entries.length)%entries.length;const item=entries[this.winnerTickerIndex];main.textContent=item.playerName||'Ganador/a';sub.textContent=`${item.prizeLabel||labels[item.type]||item.type} · Cartón ${item.cardNumber}`;dots.innerHTML=entries.length>1?entries.map((_,i)=>`<i class="${i===this.winnerTickerIndex?'active':''}"></i>`).join(''):''}
